-- =============================================================================
-- V1__baseline_schema.sql  (PostgreSQL)
--
-- PURPOSE
--   Full schema for a brand-new, empty PostgreSQL database. Flyway runs this
--   from scratch on first startup. Ported from the original MySQL baseline:
--     - AUTO_INCREMENT      -> bigint GENERATED BY DEFAULT AS IDENTITY
--     - enum(...)           -> varchar(255) (entities use EnumType.STRING)
--     - bit(1)              -> boolean
--     - datetime(6)         -> timestamp(6)
--     - double              -> double precision
--     - table `user`        -> "users" (USER is reserved in PostgreSQL)
--
-- Tables are ordered so foreign-key dependencies are always created before
-- the tables that reference them.
-- =============================================================================

CREATE TABLE users (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email varchar(255) NOT NULL,
  name varchar(255),
  password varchar(255),
  phone varchar(255),
  role varchar(255) NOT NULL,
  CONSTRAINT uk_users_email UNIQUE (email),
  CONSTRAINT ck_users_role CHECK (role IN ('ADMIN','USER'))
);

CREATE TABLE predefined_items (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name varchar(255) NOT NULL,
  price numeric(38,2),
  CONSTRAINT uk_predefined_items_name UNIQUE (name)
);

CREATE TABLE trucks (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  capacity_kg integer NOT NULL,
  is_active boolean,
  reg_number varchar(255) NOT NULL,
  size varchar(255) NOT NULL,
  CONSTRAINT uk_trucks_reg_number UNIQUE (reg_number),
  CONSTRAINT ck_trucks_size CHECK (size IN ('LARGE','MEDIUM','SMALL'))
);

CREATE TABLE drivers (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  is_active boolean,
  license_no varchar(255) NOT NULL,
  name varchar(255) NOT NULL,
  phone varchar(255) NOT NULL,
  CONSTRAINT uk_drivers_phone UNIQUE (phone)
);

CREATE TABLE bookings (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_at timestamp(6),
  distance_km double precision,
  drop_address varchar(255),
  pickup_address varchar(255),
  scheduled_date date,
  status varchar(255),
  time_slot varchar(255),
  total_amount numeric(38,2),
  updated_at timestamp(6),
  user_id bigint NOT NULL,
  CONSTRAINT fk_bookings_user FOREIGN KEY (user_id) REFERENCES users (id),
  CONSTRAINT ck_bookings_status CHECK (status IN ('CANCELLED','COMPLETED','CONFIRMED','IN_PROGRESS','PENDING')),
  CONSTRAINT ck_bookings_time_slot CHECK (time_slot IN ('EVENING','MORNING'))
);
CREATE INDEX idx_bookings_user_id ON bookings (user_id);

CREATE TABLE booking_items (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  custom_name varchar(255),
  price numeric(38,2) NOT NULL,
  quantity integer NOT NULL,
  size varchar(255),
  booking_id bigint NOT NULL,
  predefined_item_id bigint,
  CONSTRAINT fk_booking_items_predefined_item FOREIGN KEY (predefined_item_id) REFERENCES predefined_items (id),
  CONSTRAINT fk_booking_items_booking FOREIGN KEY (booking_id) REFERENCES bookings (id),
  CONSTRAINT ck_booking_items_size CHECK (size IN ('LARGE','MEDIUM','SMALL'))
);
CREATE INDEX idx_booking_items_booking_id ON booking_items (booking_id);
CREATE INDEX idx_booking_items_predefined_item_id ON booking_items (predefined_item_id);

CREATE TABLE booking_slots (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_at timestamp(6),
  slot_date date NOT NULL,
  time_slot varchar(255) NOT NULL,
  booking_id bigint NOT NULL,
  driver_id bigint NOT NULL,
  truck_id bigint NOT NULL,
  CONSTRAINT uq_truck_slot UNIQUE (truck_id, slot_date, time_slot),
  CONSTRAINT uq_driver_slot UNIQUE (driver_id, slot_date, time_slot),
  CONSTRAINT uk_booking_slots_booking UNIQUE (booking_id),
  CONSTRAINT fk_booking_slots_booking FOREIGN KEY (booking_id) REFERENCES bookings (id),
  CONSTRAINT fk_booking_slots_driver FOREIGN KEY (driver_id) REFERENCES drivers (id),
  CONSTRAINT fk_booking_slots_truck FOREIGN KEY (truck_id) REFERENCES trucks (id),
  CONSTRAINT ck_booking_slots_time_slot CHECK (time_slot IN ('EVENING','MORNING'))
);

CREATE TABLE payments (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  amount numeric(38,2) NOT NULL,
  created_at timestamp(6),
  currency varchar(255) NOT NULL,
  payment_method varchar(255),
  razorpay_order_id varchar(255) NOT NULL,
  razorpay_payment_id varchar(255),
  razorpay_signature varchar(255),
  status varchar(255) NOT NULL,
  updated_at timestamp(6),
  booking_id bigint NOT NULL,
  CONSTRAINT uk_payments_razorpay_order_id UNIQUE (razorpay_order_id),
  CONSTRAINT fk_payments_booking FOREIGN KEY (booking_id) REFERENCES bookings (id),
  CONSTRAINT ck_payments_status CHECK (status IN ('CREATED','FAILED','SUCCESS'))
);
CREATE INDEX idx_payments_booking_id ON payments (booking_id);
